package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class GrayPaintScale_getPaint_TriageGen1Test {









    @Test
    public void testGetPaint_MidValue() {
        // To get a non-zero gray, we need (v % lower) to be non-zero.
        // Let lower = 0, upper = 100.
        // But division by zero or modulo zero might occur if lower is 0.
        // Let's use lower = 10, upper = 110.
        // If value = 15, v = 15.
        // g = (int) ((15 % 10) / (110 - 10) * 255.0) 
        // g = (int) (5 / 100 * 255.0) = (int) (0.05 * 255) = (int) 12.75 = 12
        double lower = 10.0;
        double upper = 110.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        Paint paint = scale.getPaint(15.0);

        assertNotNull(paint);
        assertEquals(new Color(12, 12, 12), paint);
    }


}

package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class GrayPaintScale_getPaint_TriageGen1Test {











    @Test
    public void testGetPaint_MaxGrayValue() {
        // To maximize g, we want (v % lower) / (upper - lower) to be close to 1.
        // This is mathematically difficult with the current formula: (v % lower) 
        // is always < lower. So (v % lower) / (upper - lower) < lower / (upper - lower).
        // If lower = 100, upper = 110.
        // v = 109.9
        // g = (int) ((109.9 % 100) / (110 - 100) * 255.0)
        // g = (int) (9.9 / 10 * 255.0) = (int) (0.99 * 255) = (int) 252.45 = 252
        double lower = 100.0;
        double upper = 110.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        Paint paint = scale.getPaint(109.9);

        assertNotNull(paint);
        assertEquals(new Color(252, 252, 252), paint);
    }
}
